// Ink Bloom: nested domain warping (noise fed through noise fed through
// noise) gives folding, marbled liquid. The journey slides every layer
// through noise space in different directions, so the fluid keeps folding
// into new shapes; on each beat the kick shoves it a step further.

#define TAU 6.28318531

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  mat2 m = mat2(0.8, 0.6, -0.6, 0.8);
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 5; i++) {
    v += a * noise(p);
    p = m * p * 2.03;
    a *= 0.5;
  }
  return v;
}

// Rainbow and warm/cool palettes, blended along the journey.
vec3 palette(float t, float j) {
  vec3 d = mix(vec3(0.0, 0.33, 0.67), vec3(0.0, 0.1, 0.2), 0.5 + 0.5 * sin(j * 0.05));
  return 0.5 + 0.5 * cos(TAU * (t + d));
}

vec3 shader(vec2 uv, float time) {
  float j = drift + kick;
  vec2 p = (uv - 0.5) * vec2(resolution.x / resolution.y, 1.0);

  // Zoom breathes by itself around the chosen scale; the whole field turns.
  float zoom = mix(1.5, 6.0, scale) * (1.0 + 0.2 * sin(j * 0.07));
  float a = j * 0.03;
  p = mat2(cos(a), -sin(a), sin(a), cos(a)) * p * zoom;

  // Turbulence swells and calms on its own; the control sets the average.
  float storm = mix(0.6, 5.0, turbulence) * (0.75 + 0.35 * sin(j * 0.13));

  vec2 q = vec2(
    fbm(p + vec2(0.0, 0.0) + j * vec2(0.31, 0.11)),
    fbm(p + vec2(5.2, 1.3) - j * vec2(0.13, 0.27))
  );
  vec2 r = vec2(
    fbm(p + storm * q + vec2(1.7, 9.2) + j * vec2(0.17, -0.07)),
    fbm(p + storm * q + vec2(8.3, 2.8) - j * vec2(0.05, 0.19))
  );
  float f = fbm(p + storm * r);

  // Colour runs in ribbons along the folded field, like marbled paper:
  // the warp stretches and curls them. More marbling means more, thinner
  // ribbons with darker seams between them.
  float v = f * 1.6 + length(q) * 0.6 + r.x * 0.4;
  float stripes = v * mix(1.0, 6.0, marble);
  vec3 col = palette(stripes + colour + j * 0.017, j);
  float seam = abs(fract(stripes) - 0.5) * 2.0;
  col *= 1.0 - marble * 0.9 * smoothstep(0.7, 1.0, seam);
  // Depth: hollows of the fold darken, crests catch light.
  col *= 0.35 + 0.9 * smoothstep(0.2, 0.8, f);
  col += 0.25 * pow(smoothstep(0.55, 0.95, f), 3.0);

  col *= 1.0 - 0.4 * smoothstep(0.35, 1.0, length(uv - 0.5) * 1.6);
  return clamp(col, 0.0, 1.0);
}
